import { Agent, tool } from '@openai/agents-core';
import { TemporalOpenAIRunner } from '@temporalio/openai-agents/workflow';
import z from 'zod';

export async function tracedAgent(prompt: string): Promise<string> {
  const addTool = tool({
    name: 'add',
    description: 'Add two numbers together.',
    parameters: z.object({ a: z.number().describe('First number'), b: z.number().describe('Second number') }),
    execute: async ({ a, b }) => String(a + b),
  });

  const agent = new Agent({
    name: 'TracedAgent',
    instructions: 'You are a math assistant. Use the add tool to compute sums.',
    tools: [addTool],
  });
  const result = await new TemporalOpenAIRunner().run(agent, prompt);
  return result.finalOutput ?? '';
}

import { NativeConnection, Worker } from '@temporalio/worker';
import { OpenAIAgentsPlugin } from '@temporalio/openai-agents';
import { OpenAIProvider } from '@openai/agents-openai';
import { OpenAITracingExporter } from '@openai/agents-openai';
import { addTraceProcessor, BatchTraceProcessor } from '@openai/agents-core';
import { trace } from '@opentelemetry/api';
import { createTracerProvider } from '@temporalio/openai-agents/otel';
import { RecordingTracingProcessor } from './recording-processor';

type TracingMode = 'openai' | 'custom' | 'otel';

async function run() {
  const apiKey = [REDACTED];
  if (!apiKey) {
    throw new Error('OPENAI_API_KEY environment variable is required');
  }

  const mode = (process.argv[2] ?? process.env.TRACING_MODE ?? 'custom') as TracingMode;
  console.log(`Tracing mode: ${mode}`);

  let useOtelInstrumentation = false;
  switch (mode) {
    case 'openai':
      addTraceProcessor(new BatchTraceProcessor(new OpenAITracingExporter()));
      break;
    case 'custom':
      addTraceProcessor(new RecordingTracingProcessor());
      break;
    case 'otel':
      trace.setGlobalTracerProvider(createTracerProvider());
      useOtelInstrumentation = true;
      break;
    default:
      throw new Error(`Unknown tracing mode: ${mode}`);
  }

  const connection = await NativeConnection.connect({ address: 'localhost:7233' });
  try {
    const worker = await Worker.create({
      connection,
      taskQueue: 'openai-agents-tracing',
      workflowsPath: require.resolve('./workflows'),
      // @@@SNIPSTART typescript-openai-agents-tracing-worker
      plugins: [
        new OpenAIAgentsPlugin({
          modelProvider: new OpenAIProvider({ apiKey }),
          modelParams: { useLocalActivity: true },
          interceptorOptions: { useOtelInstrumentation, addTemporalSpans: true },
        }),
      ],
      // @@@SNIPEND
      bundlerOptions: {
        webpackConfigHook: (config) => ({
          ...config,
          resolve: {
            ...config.resolve,
            conditionNames: ['require', 'browser', 'default'],
          },
        }),
      },
    });
    await worker.run();
  } finally {
    await connection.close();
  }
}

run().catch((err) => {
  console.error(err);
  process.exit(1);
});

import { Connection, Client } from '@temporalio/client';
import { OpenAIAgentsPlugin } from '@temporalio/openai-agents';
import { OpenAIProvider } from '@openai/agents-openai';
import { tracedAgent } from './workflows';
import { nanoid } from 'nanoid';

async function run() {
  const apiKey = [REDACTED];
  if (!apiKey) {
    throw new Error('OPENAI_API_KEY environment variable is required');
  }

  const prompt = process.argv[2] ?? 'What is 42 plus 58?';

  const connection = await Connection.connect();
  const client = new Client({
    connection,
    plugins: [new OpenAIAgentsPlugin({ modelProvider: new OpenAIProvider({ apiKey }) })],
  });

  const handle = await client.workflow.start(tracedAgent, {
    taskQueue: 'openai-agents-tracing',
    workflowId: 'openai-agents-' + nanoid(),
    args: [prompt],
  });

  console.log(`Started workflow ${handle.workflowId}`);
  console.log(await handle.result());
}

run().catch((err) => {
  console.error(err);
  process.exit(1);
});

import type { Span, SpanData, Trace, TracingProcessor } from '@openai/agents-core';

export class RecordingTracingProcessor implements TracingProcessor {
  readonly spanTypes: string[] = [];
  readonly traceIds: string[] = [];

  async onTraceStart(trace: Trace): Promise<void> {
    this.traceIds.push(trace.traceId);
  }

  async onTraceEnd(_trace: Trace): Promise<void> {}

  async onSpanStart(_span: Span<SpanData>): Promise<void> {}

  async onSpanEnd(span: Span<SpanData>): Promise<void> {
    this.spanTypes.push(span.spanData.type);
  }

  async shutdown(_timeout?: number): Promise<void> {}

  async forceFlush(): Promise<void> {}
}

import {
  Usage,
  type AgentOutputItem,
  type Model,
  type ModelProvider,
  type ModelRequest,
  type ModelResponse,
  type StreamEvent,
} from '@openai/agents-core';

export class FakeModel implements Model {
  readonly requests: ModelRequest[] = [];
  private getNext: () => ModelResponse;
  constructor(source: ModelResponse[]) {
    let index = 0;
    this.getNext = () => {
      if (index >= source.length) {
        throw new Error(
          `FakeModel: no more canned responses (called ${index + 1} times, only ${source.length} provided)`,
        );
      }
      return source[index++]!;
    };
  }
  async getResponse(request: ModelRequest): Promise<ModelResponse> {
    this.requests.push(request);
    return this.getNext();
  }
  // eslint-disable-next-line require-yield
  async *getStreamedResponse(_request: ModelRequest): AsyncIterable<StreamEvent> {
    throw new Error('Streaming not supported in FakeModel');
  }
}

export class FakeModelProvider implements ModelProvider {
  readonly requestedModelNames: (string | undefined)[] = [];
  readonly model: FakeModel;
  constructor(source: ModelResponse[]) {
    this.model = new FakeModel(source);
  }
  getModel(name?: string): Model {
    this.requestedModelNames.push(name);
    return this.model;
  }
}

function fakeUsage(outputTokens: number): Usage {
  return new Usage({ requests: 1, inputTokens: 10, outputTokens, totalTokens: 10 + outputTokens });
}

export function textResponse(text: string): ModelResponse {
  const output: AgentOutputItem[] = [
    { type: 'message', role: 'assistant', content: [{ type: 'output_text', text }], status: 'completed' },
  ];
  return { output, usage: fakeUsage(text.length) };
}

export function toolCallResponse(toolName: string, args: Record<string, unknown>): ModelResponse {
  const output: AgentOutputItem[] = [
    {
      type: 'function_call',
      name: toolName,
      arguments: JSON.stringify(args),
      callId: `call_fake_${toolName}`,
      status: 'completed',
    },
  ];
  return { output, usage: fakeUsage(20) };
}
